import React, { useCallback, useEffect, useState } from 'react';
import { BrowserRouter, Navigate, Route, Routes, useNavigate } from 'react-router-dom';
import StudentApp from './student/StudentApp';
import SchoolApp from './school/SchoolApp';
import LoginPage from './pages/LoginPage';
import { AuthUserPublic, fetchCurrentUser, getAuthToken, setAuthToken } from './api';
import './App.css';

export const GUEST_MODE_KEY = 'psyqa_guest_mode';

function RootRedirect() {
  const token = getAuthToken();
  const guest = sessionStorage.getItem(GUEST_MODE_KEY) === '1';
  if (guest) return <Navigate to="/student" replace />;
  if (token) return <Navigate to="/login" replace />;
  return <Navigate to="/login" replace />;
}

function StudentRoute() {
  const navigate = useNavigate();
  const [ready, setReady] = useState(false);
  const [sessionUser, setSessionUser] = useState<AuthUserPublic | null>(null);
  const [guestMode, setGuestMode] = useState(false);

  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      const guest = sessionStorage.getItem(GUEST_MODE_KEY) === '1';
      const token = getAuthToken();
      if (guest && !token) {
        if (!cancelled) {
          setGuestMode(true);
          setSessionUser(null);
          setReady(true);
        }
        return;
      }
      if (!token) {
        navigate('/login', { replace: true });
        return;
      }
      try {
        const { user } = await fetchCurrentUser();
        if (user.role === 'counselor' || user.role === 'admin') {
          navigate('/school', { replace: true });
          return;
        }
        if (!cancelled) {
          sessionStorage.removeItem(GUEST_MODE_KEY);
          setGuestMode(false);
          setSessionUser(user);
          setReady(true);
        }
      } catch {
        setAuthToken(null);
        navigate('/login', { replace: true });
      }
    };
    run();
    return () => {
      cancelled = true;
    };
  }, [navigate]);

  const onLogout = useCallback(() => {
    setAuthToken(null);
    sessionStorage.removeItem(GUEST_MODE_KEY);
    navigate('/login', { replace: true });
  }, [navigate]);

  if (!ready) {
    return (
      <div className="login-overlay">
        <div className="login-spinner-card">
          <p>正在进入学生端…</p>
        </div>
      </div>
    );
  }

  return <StudentApp sessionUser={sessionUser} guestMode={guestMode} onLogout={onLogout} />;
}

function SchoolRoute() {
  const navigate = useNavigate();
  const [ready, setReady] = useState(false);
  const [sessionUser, setSessionUser] = useState<AuthUserPublic | null>(null);

  useEffect(() => {
    let cancelled = false;
    const run = async () => {
      const token = getAuthToken();
      if (!token) {
        navigate('/login', { replace: true });
        return;
      }
      try {
        const { user } = await fetchCurrentUser();
        if (user.role !== 'counselor' && user.role !== 'admin') {
          navigate('/student', { replace: true });
          return;
        }
        if (!cancelled) {
          sessionStorage.removeItem(GUEST_MODE_KEY);
          setSessionUser(user);
          setReady(true);
        }
      } catch {
        setAuthToken(null);
        navigate('/login', { replace: true });
      }
    };
    run();
    return () => {
      cancelled = true;
    };
  }, [navigate]);

  const onLogout = useCallback(() => {
    setAuthToken(null);
    sessionStorage.removeItem(GUEST_MODE_KEY);
    navigate('/login', { replace: true });
  }, [navigate]);

  if (!ready || !sessionUser) {
    return (
      <div className="login-overlay">
        <div className="login-spinner-card">
          <p>正在进入学校端…</p>
        </div>
      </div>
    );
  }

  return <SchoolApp sessionUser={sessionUser} onLogout={onLogout} />;
}

function App() {
  return (
    <BrowserRouter>
      <Routes>
        <Route path="/" element={<RootRedirect />} />
        <Route path="/login" element={<LoginPage />} />
        <Route path="/student/*" element={<StudentRoute />} />
        <Route path="/school/*" element={<SchoolRoute />} />
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
